package com.example.demodatn.service.hotro;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.context.WebApplicationContext;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.test.web.servlet.setup.MockMvcBuilders;
import com.example.demodatn.repository.hotro.ChatConversationRepository;
import com.example.demodatn.dto.hotro.SupportChatRequest;
import static org.junit.jupiter.api.Assertions.*;
import static org.springframework.security.test.web.servlet.setup.SecurityMockMvcConfigurers.springSecurity;
import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
import java.util.*;
@SpringBootTest @Transactional
class SupportChatInboxIntegrationTest {
 @Autowired jakarta.persistence.EntityManager em;@Autowired SupportChatService chat;@Autowired SupportChatInboxService inbox;@Autowired JdbcTemplate jdbc;@Autowired ChatConversationRepository conversations;@Autowired WebApplicationContext context;
 SupportChatService.Actor customer,admin;long id;MockMvc mvc;
 @BeforeEach void setup(){com.example.demodatn.TestDatabaseGuard.check(jdbc);String name="gd29-"+UUID.randomUUID().toString().substring(0,10);int role=jdbc.queryForObject("SELECT id FROM roles WHERE name='ROLE_USER'",Integer.class);int uid=jdbc.queryForObject("INSERT users(username,password,role_id,status,must_change_password) OUTPUT INSERTED.id VALUES(?,'not-login',?,1,0)",Integer.class,name,role);jdbc.update("INSERT customers(customer_code,full_name,email,phone,status,user_id) VALUES(?,N'Nguyễn Văn Ánh',?,?,1,?)",name,name+"@example.test",String.format("+849%08d",uid),uid);customer=new SupportChatService.Actor(name,null);admin=new SupportChatService.Actor("admin",null);id=chat.open(customer,null,null,"inbox-test").id();mvc=MockMvcBuilders.webAppContextSetup(context).apply(springSecurity()).build();}
 @Test void sharedAssignmentAuditReleaseCloseReopenAndFirstReply(){chat.act(id,admin,"claim");int user=chat.identity(admin).userId();assertEquals(user,conversations.findById(id).orElseThrow().getAssignedUserId());chat.act(id,admin,"queue");assertNull(conversations.findById(id).orElseThrow().getAssignedUserId());chat.send(id,new SupportChatRequest(UUID.randomUUID().toString(),"VAN_BAN","Xin chào bạn",null,null),null,admin,"inbox-test",null);assertEquals(user,conversations.findById(id).orElseThrow().getAssignedUserId());chat.act(id,admin,"close");assertEquals("DA_DONG",conversations.findById(id).orElseThrow().getStatus());chat.send(id,new SupportChatRequest(UUID.randomUUID().toString(),"VAN_BAN","Khách nhắn mở lại",null,null),null,customer,"inbox-test",null);assertEquals("DANG_XU_LY",conversations.findById(id).orElseThrow().getStatus());chat.act(id,admin,"queue");chat.act(id,admin,"close");chat.send(id,new SupportChatRequest(UUID.randomUUID().toString(),"VAN_BAN","Mở lại hàng chờ",null,null),null,customer,"inbox-test",null);assertEquals("MOI",conversations.findById(id).orElseThrow().getStatus());assertTrue(jdbc.queryForObject("SELECT COUNT(*) FROM chat_action_audit WHERE hoi_thoai_id=?",Integer.class,id)>=5);}
 @Test void filtersCountsSearchAndTwentyPagination(){for(int i=0;i<24;i++){String token=SupportChatService.newToken();chat.open(new SupportChatService.Actor(null,SupportChatService.hashToken(token)),"Khách thử "+i,"gd29-search@example.test","inbox-test");}chat.send(id,new SupportChatRequest(UUID.randomUUID().toString(),"VAN_BAN","Nội dung Nguyễn Huệ",null,null),null,customer,"inbox-test",null);assertTrue(((Number)inbox.counts(admin).get("unreadMessages")).intValue()>=1);var page=(Map<?,?>)inbox.list(admin,"gd29-search","all",0);assertEquals(20,((List<?>)page.get("content")).size());assertEquals(true,page.get("hasMore"));var second=(Map<?,?>)inbox.list(admin,"gd29-search","all",1);assertEquals(4,((List<?>)second.get("content")).size());assertEquals(false,second.get("hasMore"));assertEquals(1,((List<?>)((Map<?,?>)inbox.list(admin,"Nguyễn Huệ","unread",0)).get("content")).size());chat.act(id,admin,"claim");em.flush();assertEquals(1,((List<?>)((Map<?,?>)inbox.list(admin,"Nguyễn Huệ","mine",0)).get("content")).size());}
 @Test void detailQuickRepliesAndNoCustomerImpersonation(){var d=inbox.detail(id,admin);assertEquals("Nguyễn Văn Ánh",d.get("name"));jdbc.update("UPDATE customers SET full_name=N'Tên hồ sơ đã sửa' WHERE id=?",d.get("customerId"));assertEquals("Tên hồ sơ đã sửa",inbox.detail(id,admin).get("name"));assertTrue(((List<?>)inbox.replies(admin)).size()>=5);assertThrows(org.springframework.web.server.ResponseStatusException.class,()->inbox.counts(customer));assertThrows(org.springframework.web.server.ResponseStatusException.class,()->chat.act(id,customer,"claim"));}
 @Test void routesCsrfRolesAndLegacyRedirects()throws Exception{mvc.perform(get("/admin/chat").with(user("admin").roles("ADMIN"))).andExpect(status().isOk());for(String path:List.of("/admin/support-tickets","/admin/support-tickets/1","/admin/chatbot-faq/new"))mvc.perform(get(path).with(user("admin").roles("ADMIN"))).andExpect(status().isFound()).andExpect(redirectedUrl("/admin/chat"));for(String path:List.of("/admin/chat","/admin/chat/api/counts","/admin/chat/api/conversations")){mvc.perform(get(path).with(user(customer.username()).roles("USER"))).andExpect(status().isForbidden());mvc.perform(get(path)).andExpect(status().isForbidden());}for(String action:List.of("claim","queue","close","reopen")){String path="/admin/chat/api/"+id+"/"+action;mvc.perform(post(path).with(user("admin").roles("ADMIN"))).andExpect(status().isForbidden());mvc.perform(post(path).with(user("admin").roles("ADMIN")).with(csrf().useInvalidToken())).andExpect(status().isForbidden());mvc.perform(post(path).with(user("admin").roles("ADMIN")).with(csrf())).andExpect(status().isOk());}}
 @Test void auditKeepsActorAfterUnusedEmployeeAccountDeletion(){String name="gd29-audit-"+UUID.randomUUID().toString().substring(0,8);int role=jdbc.queryForObject("SELECT id FROM roles WHERE name='ROLE_EMPLOYEE'",Integer.class);int user=jdbc.queryForObject("INSERT users(username,password,role_id,status,must_change_password) OUTPUT INSERTED.id VALUES(?,'not-login',?,1,0)",Integer.class,name,role);int employee=jdbc.queryForObject("INSERT employees(employee_code,full_name,email,phone,position,status,user_id) OUTPUT INSERTED.id VALUES(?,N'Nhân viên giả',?,?,N'Nhân viên',1,?)",Integer.class,name,name+"@example.test",String.format("+848%08d",user),user);var actor=new SupportChatService.Actor(name,null);chat.act(id,actor,"claim");chat.act(id,actor,"queue");em.flush();jdbc.update("DELETE employees WHERE id=?",employee);jdbc.update("DELETE users WHERE id=?",user);assertEquals(2,jdbc.queryForObject("SELECT COUNT(*) FROM chat_action_audit WHERE hoi_thoai_id=? AND actor_name=?",Integer.class,id,name));assertEquals(2,((java.util.List<?>)inbox.detail(id,admin).get("audit")).size());}

 @Test void migratedTicketReplyAppearsInCustomerHistoryWithSharedUnreadAndReceipt(){int owner=chat.identity(customer).customerId();String tag="gd29-ticket-"+UUID.randomUUID().toString().substring(0,8);int ticket=jdbc.queryForObject("INSERT phieu_ho_tro(ma,khach_id,ho_ten,lien_he,noi_dung,trang_thai,created_at) OUTPUT INSERTED.id VALUES(?,?,N'Khách giả','fixture@example.test',N'Phiếu cũ',N'Mới',SYSDATETIME())",Integer.class,tag,owner);long legacy=jdbc.queryForObject("INSERT chat_hoi_thoai(session_id,khach_id,legacy_ticket_id,ho_ten,lien_he,created_at,updated_at,last_message_at) OUTPUT INSERTED.id VALUES(?,?,?,N'Khách giả','fixture@example.test',SYSDATETIME(),SYSDATETIME(),SYSDATETIME())",Long.class,tag,owner,ticket);chat.send(id,new SupportChatRequest(UUID.randomUUID().toString(),"VAN_BAN","Tin hội thoại mới",null,null),null,customer,"inbox-test",null);var reply=chat.send(legacy,new SupportChatRequest(UUID.randomUUID().toString(),"VAN_BAN","Trả lời phiếu đã chuyển",null,null),null,admin,"inbox-test",null);assertEquals(1,chat.history(legacy,null,admin).messages().size());assertEquals(2,chat.history(id,null,customer).messages().size());assertEquals(1,chat.current(customer).orElseThrow().unread());chat.read(id,reply.id(),customer);em.clear();assertEquals(0,chat.current(customer).orElseThrow().unread());assertNotNull(chat.history(legacy,null,admin).messages().get(0).seenAt());}

}
